//! 🧩️ One original composite source funds preparation, pixel work, raw handoff and private retirement.
use super::*;
use semio_framework_pixels::compositing::layers::{RasterStackResult,RasterStackRetirement};
use semio_framework_value::{ValueError,ValueRefusalKind,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,retained_clone::RetainedCloneClose,work::RetainedWorkLedger};
use std::mem::ManuallyDrop;

#[derive(semio_framework_value::RetireOwned)]
#[value(send_only)]
struct CompositeData{job:Option<RasterStackJob>,retired:Option<RasterStackRetirement>,output:Option<RasterStackResult>,phase:u8}
pub struct RasterCompositeWork{document:usize,preparing:ManuallyDrop<Option<RasterStackPreparationWork>>,data:ManuallyDrop<Option<CompositeData>>,retirement:RetainedCloneClose,closing:bool,failed:bool}
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
impl RasterCompositeWork{
    pub fn new(document:&RasterSnapshot)->Result<Self,ValueError>{Self::from_layers(document,&document.layers,false)}
    pub fn from_layers(document:&RasterSnapshot,layers:&[RasterLayerNode],editable:bool)->Result<Self,ValueError>{let preparing=if editable{RasterStackPreparationWork::for_edit(document,layers)}else{RasterStackPreparationWork::from_layers(document,layers)}?;Ok(Self{document:document as*const _ as usize,preparing:ManuallyDrop::new(Some(preparing)),data:ManuallyDrop::new(Some(CompositeData{job:None,retired:None,output:None,phase:0})),retirement:Default::default(),closing:false,failed:false})}
    pub fn output_ready(&self)->bool{!self.closing&&!self.failed&&self.data.as_ref().is_some_and(|data|data.phase==6&&data.output.is_some())}
    pub fn demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.failed||!(1..=32768).contains(&body){return Err(refusal("raster.composite-work-inactive"))}let data=self.data.as_ref().ok_or_else(||refusal("raster.composite-work-transferred"))?;match data.phase{0=>if self.preparing.as_ref().unwrap().output_ready(){Ok(RetirementDemand{depth:1,..Default::default()})}else{self.preparing.as_ref().unwrap().demands(body)},2=>self.preparing.as_ref().unwrap().close_demands(body),3=>Ok(data.job.as_ref().unwrap().next_work_demand()),5=>data.retired.as_ref().unwrap().owner.selected_demand(body),_=>Ok(RetirementDemand{depth:1,..Default::default()})}}
    pub fn advance(&mut self,document:&RasterSnapshot,body:usize,grant:RetainedCloneGrant)->RetainedWorkOutcome{
        if grant.maximum_items==0{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}let demand=match self.demands(body){Ok(demand)=>demand,Err(error)=>return RetainedWorkOutcome{result:Err(error),work:0}};if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,demand){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}if self.document!=document as*const _ as usize{self.failed=true;return RetainedWorkOutcome{result:Err(refusal("raster.composite-source-revision-changed")),work:0}}
        let data=self.data.as_mut().unwrap();let mut cpu=1;let result=match data.phase{
            0=>{let preparing=self.preparing.as_mut().unwrap();if preparing.output_ready(){data.phase=1;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()}))}else{let turn=preparing.advance(document,body,grant);cpu=turn.work;turn.result.map(|step|RetainedCloneStep::Progress(step.progress()))}},
            1=>{let turn=self.preparing.as_mut().unwrap().take_input(grant);cpu=turn.work;turn.result.map(|output|if let Some((input,progress))=output{data.job=Some(RasterStackJob::new(input));self.preparing.as_mut().unwrap().cancel();data.phase=2;RetainedCloneStep::Progress(progress)}else{RetainedCloneStep::Progress(Default::default())})},
            2=>{let preparing=self.preparing.as_mut().unwrap();let turn=preparing.close_step(grant);cpu=turn.work;if preparing.terminal_is_empty(){self.preparing.take();data.phase=3;}turn.result.map(|step|RetainedCloneStep::Progress(step.progress()))},
            3=>{let job=data.job.as_mut().unwrap();let mut work=RetainedWorkLedger::new(grant);let result=job.advance(256,&mut work);cpu=job.last_turn_work();let progress=work.receipt();match result{Ok(state)=>{if state.done{data.phase=4;}Ok(RetainedCloneStep::Progress(progress))},Err(_)=>Err(refusal("raster.composite-pixel-work-refused").with_retained_progress(progress))}},
            4=>{let(retired,output)=data.job.take().unwrap().into_retirement();data.retired=Some(retired);data.output=output;if data.output.is_some(){data.phase=5;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()}))}else{Err(refusal("raster.composite-output-unavailable"))}},
            5=>{let retired=data.retired.as_mut().unwrap();let result=retired.close_step(grant);cpu=retired.owner.last_turn_work();if retired.terminal_is_empty(){data.retired=None;data.phase=6;}result.map(|step|if data.phase==6{RetainedCloneStep::Complete(step.progress())}else{RetainedCloneStep::Progress(step.progress())})},
            6=>Ok(RetainedCloneStep::Complete(Default::default())),_=>Err(refusal("raster.composite-work-phase")),
        };if result.is_err(){self.failed=true;}RetainedWorkOutcome{result,work:cpu}
    }
    pub fn take_result(&mut self,grant:RetainedCloneGrant)->RetainedWorkOutcome<Option<(RasterStackResult,RetainedCloneProgress)>>{if !self.output_ready(){return RetainedWorkOutcome{result:Err(refusal("raster.composite-output-unavailable")),work:0}}if grant.maximum_items==0||grant.maximum_depth==0{return RetainedWorkOutcome{result:Ok(None),work:0}}let data=self.data.as_mut().unwrap();let result=data.output.take().unwrap();data.phase=7;RetainedWorkOutcome{result:Ok(Some((result,RetainedCloneProgress{copied_items:1,..Default::default()}))),work:1}}
    pub fn cancel(&mut self){self.closing=true;if let Some(preparing)=self.preparing.as_mut(){preparing.cancel();}}
    pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(preparing)=self.preparing.as_ref(){return preparing.close_demands(body)}self.retirement.next_owner_demands::<CompositeData>(self.data.is_some(),&None,body)}
    pub fn close_step(&mut self,grant:RetainedCloneGrant)->RetainedWorkOutcome{if !self.closing{return RetainedWorkOutcome{result:Err(refusal("raster.composite-close-intent")),work:0}}if let Some(preparing)=self.preparing.as_mut(){let turn=preparing.close_step(grant);if preparing.terminal_is_empty(){self.preparing.take();}return turn}if !self.retirement.is_empty(){return self.retirement.step_granted(grant)}let turn=self.retirement.begin_granted(&mut self.data,grant);RetainedWorkOutcome{result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Complete(Default::default()))),work:turn.work}}
    pub fn terminal_is_empty(&self)->bool{self.preparing.is_none()&&self.data.is_none()&&self.retirement.is_empty()}
}
impl Drop for RasterCompositeWork{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"composite work retains original private roots until funded close");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.preparing);ManuallyDrop::drop(&mut self.data)}}}}
